 import unittest
from candidate import is_palindrome

class TestPalindrome(unittest.TestCase):
    def test_empty_string(self):
        self.assertTrue(is_palindrome(''))

    def test_single_character_palindrome(self):
        self.assertTrue(is_palindrome('a'))

    def test_simple_palindrome(self):
        self.assertTrue(is_palindrome('aba'))

    def test_long_palindrome(self):
        self.assertTrue(is_palindrome('aaaaa'))

    def test_palindrome_with_non_alphanumeric_characters(self):
        self.assertTrue(is_palindrome('123abc!@#$!@#abc123'))

    def test_non_palindrome(self):
        self.assertFalse(is_palindrome('zbcd'))

    def test_odd_length_palindrome(self):
        self.assertTrue(is_palindrome('letottelevetolle'))

    def test_palindrome_with_case_sensitivity(self):
        self.assertFalse(is_palindrome('mom'))
        self.assertTrue(is_palindrome('Mom'))

    def test_empty_string_return(self):
        self.assertEqual(is_palindrome(''), True)

    def test_single_character_return(self):
        self.assertEqual(is_palindrome('a'), True)

    def test_invalid_input_type(self):
        self.assertRaises(TypeError, is_palindrome, 123)

if __name__ == '__main__':
    unittest.main()
